import{_ as t,o as a,c as i,ak as o}from"./chunks/framework.sV-XtlWr.js";const y=JSON.parse('{"title":"One-click deploy","description":"Stand up a Piwi instance on Railway, Render, Fly.io, Koyeb, Coolify or Dokploy from a template, and what to check before you rely on it.","frontmatter":{"title":"One-click deploy","description":"Stand up a Piwi instance on Railway, Render, Fly.io, Koyeb, Coolify or Dokploy from a template, and what to check before you rely on it.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/operate/one-click-deploy.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/operate/one-click-deploy.html"}],["meta",{"property":"og:title","content":"One-click deploy | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Stand up a Piwi instance on Railway, Render, Fly.io, Koyeb, Coolify or Dokploy from a template, and what to check before you rely on it."}]]},"headers":[],"relativePath":"operate/one-click-deploy.md","filePath":"operate/one-click-deploy.md","lastUpdated":1790454954000}'),s={name:"operate/one-click-deploy.md"};function n(r,e,l,h,d,p){return a(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="one-click-deploy" tabindex="-1">One-click deploy <a class="header-anchor" href="#one-click-deploy" aria-label="Permalink to &quot;One-click deploy&quot;">​</a></h1><p>If you don&#39;t have a server to run Docker on, these templates stand up an instance on a hosting provider instead. They all provision the same thing: <strong>one container, one persistent volume mounted at <code>/app/.data</code>, authentication on, and <code>PIWI_SECRET_KEY</code> / <code>PIWI_AUTH_SECRET</code> generated by the platform</strong>. The only real difference is the provider&#39;s own volume and pricing model.</p><p>The manifests are generated from the same variable registry as the <a href="/reference/configuration.html">configuration reference</a>, so they can&#39;t drift from what the app actually reads. The <a href="/reference/configuration/generator.html">configuration generator</a> writes the same manifests for your own choices of variables.</p><table tabindex="0"><thead><tr><th>Provider</th><th>How</th><th>Persistent volume</th><th>Notes</th></tr></thead><tbody><tr><td><a href="#railway">Railway</a></td><td>Button</td><td>Yes</td><td>Managed PostgreSQL available alongside</td></tr><tr><td><a href="#render">Render</a></td><td>Button</td><td>Yes, on a paid instance</td><td>Fully repo-driven, nothing to configure by hand</td></tr><tr><td><a href="#fly-io">Fly.io</a></td><td><code>fly launch</code></td><td>Yes</td><td>One command rather than a button; cheapest always-on option</td></tr><tr><td><a href="#koyeb">Koyeb</a></td><td>Button</td><td>Volume attached afterwards</td><td>Fastest to a running URL, but see the warning below</td></tr><tr><td><a href="#coolify-dokploy">Coolify / Dokploy</a></td><td>Paste a Compose file</td><td>Yes</td><td>Onto a server you already own</td></tr></tbody></table><p>Not supported as one-click: <strong>Vercel, Netlify and DigitalOcean App Platform</strong> have no persistent disk, so Piwi would need PostgreSQL <em>and</em> a bring-your-own <a href="./storage.html#s3-compatible-storage">S3 bucket</a>, at which point it isn&#39;t one click. <a href="./deployment.html">Deploy it</a> to a machine with Docker instead.</p><h2 id="railway" tabindex="-1">Railway <a class="header-anchor" href="#railway" aria-label="Permalink to &quot;Railway&quot;">​</a></h2><p>Railway publishes templates from its own dashboard rather than from a file in this repository, so the template&#39;s exact contents live in <a href="https://github.com/PiwiTests/platform/blob/main/deploy/railway/template.md" target="_blank" rel="noreferrer"><code>deploy/railway/template.md</code></a> and the repo ships a <a href="https://github.com/PiwiTests/platform/blob/main/railway.json" target="_blank" rel="noreferrer"><code>railway.json</code></a> pinning the health check to <code>/api/health</code> and the replica count to 1.</p><blockquote><p><strong>No button yet.</strong> Until the template is published on Railway, create a service from the <code>phenx/piwitests-server:latest</code> image, add a volume mounted at <code>/app/.data</code>, and copy the variables from <code>deploy/railway/template.md</code>.</p></blockquote><p>Railway injects <code>PORT</code>, which the image honors.</p><h2 id="render" tabindex="-1">Render <a class="header-anchor" href="#render" aria-label="Permalink to &quot;Render&quot;">​</a></h2><p>Render reads <a href="https://github.com/PiwiTests/platform/blob/main/render.yaml" target="_blank" rel="noreferrer"><code>render.yaml</code></a> straight from the repository, so the button is genuinely one click:</p><p><a href="https://render.com/deploy?repo=https://github.com/PiwiTests/platform" target="_blank" rel="noreferrer"><img src="https://render.com/images/deploy-to-render-button.svg" alt="Deploy to Render"></a></p><p>The blueprint asks for a <strong>paid instance type</strong>, deliberately: Render&#39;s free web services have no disk, and without one the database and every stored trace are discarded on each redeploy. It also sets <code>autoDeploy: false</code> so pushes to this repository don&#39;t redeploy your instance.</p><p>Set <code>PIWI_SITE_URL</code> to the service&#39;s public URL after the first deploy, so email links and OAuth callbacks point at the right origin.</p><h2 id="fly-io" tabindex="-1">Fly.io <a class="header-anchor" href="#fly-io" aria-label="Permalink to &quot;Fly.io&quot;">​</a></h2><p>Fly has no browser button, but <a href="https://github.com/PiwiTests/platform/blob/main/fly.toml" target="_blank" rel="noreferrer"><code>fly.toml</code></a> makes it one command plus the secrets:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fly</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> launch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-deploy</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # accepts the committed fly.toml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fly</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secrets</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PIWI_SECRET_KEY=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rand</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -hex</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">PIWI_AUTH_SECRET=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rand</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -hex</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fly</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span></span></code></pre></div><p>If <code>fly launch</code> picks a different app name because yours is taken, update <code>PIWI_SITE_URL</code> in <code>fly.toml</code> to match. Autoscaling is deliberately off (<code>auto_stop_machines = false</code>, <code>min_machines_running = 1</code>): the notification and retention sweeps run in-process, so a suspended machine silently stops doing scheduled work.</p><h2 id="koyeb" tabindex="-1">Koyeb <a class="header-anchor" href="#koyeb" aria-label="Permalink to &quot;Koyeb&quot;">​</a></h2><p>Koyeb carries the whole service definition in the URL, so nothing needs to be in the repository:</p><p><a href="https://app.koyeb.com/deploy?type=docker&amp;image=docker.io/phenx/piwitests-server:latest&amp;name=piwi&amp;instance_type=small&amp;regions=fra&amp;ports=3000;http;/&amp;env%5BPIWI_AUTH_ENABLED%5D=true" target="_blank" rel="noreferrer"><img src="https://www.koyeb.com/static/images/deploy/button.svg" alt="Deploy to Koyeb"></a></p><blockquote><p><strong>The button alone gives you an ephemeral disk.</strong> Koyeb volumes can&#39;t be attached from a deploy URL, so until you attach one, the database and every stored trace are lost on redeploy. Volumes are region-scoped and only standard (not free or eco) instances can mount them:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">koyeb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> volumes</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> piwi-data</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --region</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fra</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --size</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">koyeb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> piwi/piwi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --volumes</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> piwi-data:/app/.data</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">koyeb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> piwi/piwi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --checks</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 3000:http:/api/health</span></span></code></pre></div></blockquote><p>Set <code>PIWI_SECRET_KEY</code>, <code>PIWI_AUTH_SECRET</code> and <code>PIWI_SITE_URL</code> in the Koyeb console after the first deploy, because the URL can&#39;t generate secrets. The full command list is kept in <a href="https://github.com/PiwiTests/platform/blob/main/deploy/koyeb-deploy-url.txt" target="_blank" rel="noreferrer"><code>deploy/koyeb-deploy-url.txt</code></a>.</p><h2 id="coolify-dokploy" tabindex="-1">Coolify / Dokploy <a class="header-anchor" href="#coolify-dokploy" aria-label="Permalink to &quot;Coolify / Dokploy&quot;">​</a></h2><p>Both consume a Compose file, so one stack covers them. In Coolify: <strong>Add a new resource → Service →</strong> paste <a href="https://github.com/PiwiTests/platform/blob/main/deploy/coolify/docker-compose.yml" target="_blank" rel="noreferrer"><code>deploy/coolify/docker-compose.yml</code></a>. It uses Coolify&#39;s magic variables, so the domain and both secrets are generated for you and Traefik routing and TLS are wired up automatically.</p><h2 id="before-you-rely-on-any-of-them" tabindex="-1">Before you rely on any of them <a class="header-anchor" href="#before-you-rely-on-any-of-them" aria-label="Permalink to &quot;Before you rely on any of them&quot;">​</a></h2><ul><li><strong>One instance, always.</strong> Don&#39;t scale the service past a single replica. SQLite requires it, and even on PostgreSQL the SSE event bus and the cron sweeps are in-process.</li><li><strong>Budget disk by retention.</strong> Traces and HTML reports dominate: roughly 50–200 MB per run with traces enabled. The templates ask for 10 GB; raise it, or set <code>PIWI_RETENTION_DAYS</code>, before you fill it.</li><li><strong>Check the platform&#39;s request body limit and response buffering.</strong> Trace and report uploads reach hundreds of MB, and live runs use long-lived <code>text/event-stream</code> responses; see <a href="./deployment.html#reverse-proxy-https">Reverse proxy (HTTPS)</a> for what a proxy must allow.</li><li><strong>Finish the auth setup.</strong> These templates set <code>PIWI_AUTH_ENABLED=true</code>, so the first visit shows a <strong>Create the first admin account</strong> form. Complete it before sharing the URL, or provision the admin from a script as <a href="./authentication.html#initial-setup">Authentication → Initial setup</a> shows.</li><li><strong>Work down the <a href="./production-checklist.html">production checklist</a>.</strong> The templates already turn authentication on and generate both secrets; pinning a version and backups are still yours to do.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./deployment.html">Deployment</a>: Docker, Compose, Kubernetes and npx on a machine you run</li><li><a href="./production-checklist.html">Production checklist</a>: what to set before anyone else can reach the instance</li><li><a href="/reference/configuration/generator.html">Configuration generator</a>: the same manifests, with your own variables</li><li><a href="./upgrading.html">Upgrading</a>: pinning a tag and moving to a new one</li></ul>`,29)])])}const k=t(s,[["render",n]]);export{y as __pageData,k as default};
